import{z as s,x as A,o as E,c as B,q as t,j as i,D as e,d as r,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"激活重计算","description":"","frontmatter":{"title":"激活重计算","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/activation-checkpointing.md","filePath":"llm/activation-checkpointing.md","lastUpdated":1791413859000}'),p={name:"llm/activation-checkpointing.md"};function h(d,a,m,c,D,F){const n=A("Mermaid");return E(),B("div",null,[a[2]||(a[2]=t('<h1 id="激活重计算" tabindex="-1">激活重计算 <a class="header-anchor" href="#激活重计算" aria-label="Permalink to &quot;激活重计算&quot;">​</a></h1><div class="epigraph"><p>反向传播需要前向的中间量。与其全部存下来，不如只留若干检查点，缺的那些在反向时再算一遍。</p><footer>—— Chen et al., Training Deep Nets with Sublinear Memory Cost, 2016</footer></div><p><a href="/llm/nd-parallel">上一课</a>把 3D/5D 写成正交进程组上的切法：显存与吞吐都不是五维简单相除，每一维都有自己的缓冲区。缺口是激活本身。一层里注意力分数与 FFN 中间值按 \\(b,s,d\\) 堆上去，前向激活比参数大一个数量级是常事；并行切的是副本与分片，不承认中间值必须从第一次前向活到反向结束。本课写激活重计算：只保存部分前向张量，反向时从检查点重放。不重画设备网格。后课通信拓扑默认已经读完：它不节省通信和优化器状态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>反向传播对每个算子需要该算子前向的输入（有时还需要输出）。若把整张计算图画成一条长链，朴素实现会把链上几乎所有中间值留到反向结束。设一层激活体积为 \\(A\\)，共 \\(L\\) 层，仅激活就约 \\(LA\\)。参数、Adam 状态、梯度又各占一份参数量级。长上下文下 \\(A\\) 随序列线性或超线性涨，问题从「模型太大」变成「这一层的注意力中间结果太大」。</p><p><span class="marginnote">代个数感受 \\(LA\\)：隐藏维 4096、FFN 中间维 16384、batch×序列共 32k token 时，仅一层的 FFN 中间激活就约 \\(32768\\times16384\\times2\\) 字节 \\(\\approx 1\\) GB；32 层全存就是 32 GB——比 7B 模型的 fp16 参数（约 14 GB）还大一倍多。这就是「激活比参数大一个数量级」的具体来源。</span></p><p>砍 batch 能减 \\(A\\)，但会伤害吞吐和流水线填充；砍序列会改变任务；把层卸到 CPU 则引入更贵的搬运。重计算走第三条路：承认反向确实需要那些值，但不承认它们必须从第一次前向一直活到现在。</p><h3 id="次线性显存的分段" tabindex="-1">次线性显存的分段 <a class="header-anchor" href="#次线性显存的分段" aria-label="Permalink to &quot;次线性显存的分段&quot;">​</a></h3><p>Chen 等人把长度为 \\(n\\) 的算子链分段。若每隔 \\(\\sqrt{n}\\) 步留一个检查点，前向额外重计算大约 \\(\\sqrt{n}\\) 量级，激活驻留也大约 \\(\\sqrt{n}\\) 段而不是 \\(n\\)。更激进的递归分段可以把内存降到对数级，重计算次数上升。深度学习框架里更常见的是按层或按块设检查点：Transformer 的每一层只保留进入该层的隐状态，层内注意力与 FFN 的大激活丢掉，反向时整层重放。<span class="marginnote">「checkpoint 一层」和「checkpoint 整个块」差的是重计算粒度。粒太粗，一次重放太长，反向峰值显存仍高；粒太细，检查点张量本身变多，节省有限，内核启动次数上升。预训练里通常以 Transformer layer 为边界，再对层内特别大的注意力张量做选择性保存。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现上，前向包装成带检查点的函数：进入时保存输入（以及必要的随机状态），函数内部的中间激活允许释放；反向时用保存的输入再跑一遍前向，然后用这次重放产生的中间值做标准的反向。随机性必须对齐：Dropout 的掩码、随机层的种子，要在检查点里一起存，否则重放与第一次前向不是同一个函数，梯度是错的。</p><p><span class="marginnote">可以把它想象成游戏存档：检查点存的不只是「画面」（输入张量），还有「骰子种子」（RNG 状态）。读档重放必须掷出一模一样的骰子——Dropout 掩码若变了，重算出的激活就和第一次不同，拿它算梯度等于往梯度里掺随机噪声，训练会莫名变差。</span></p><p>选择性重计算比「整层全扔」更细。注意力里 softmax 的输入很大，但重算 \\(QK^\\top\\) 也贵；有的实现选择保存归一化后的张量、丢掉投影中间态，或保存 FlashAttention 的若干统计量、丢掉完整分数矩阵。Megatron 一类预训练栈把重计算分成满重计算与选择性重计算：前者层内几乎不留激活，后者留下计算代价高、体积相对可控的张量。目标是让重计算的 FLOPs 落在本来吃不满的算力空隙里，而不是把 step time 拉长一倍。</p>',13)),(E(),i(o,null,{default:e(()=>[l(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%B1%82%E8%BE%93%E5%85%A5%E4%BD%9C%E4%B8%BA%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%20--%3E%20F%5B%22%E5%89%8D%E5%90%91%EF%BC%9A%E5%A4%A7%E6%BF%80%E6%B4%BB%E7%94%A8%E5%AE%8C%E5%8D%B3%E9%87%8A%E6%94%BE%22%5D%0A%20%20F%20--%3E%20Y%5B%22%E5%B1%82%E8%BE%93%E5%87%BA%22%5D%0A%20%20Y%20--%3E%20B%5B%22%E5%8F%8D%E5%90%91%E5%88%B0%E8%BE%BE%E8%AF%A5%E5%B1%82%22%5D%0A%20%20B%20--%3E%20R%5B%22%E4%BB%8E%E6%A3%80%E6%9F%A5%E7%82%B9%E9%87%8D%E6%94%BE%E5%89%8D%E5%90%91%22%5D%0A%20%20R%20--%3E%20G%5B%22%E7%94%A8%E9%87%8D%E6%94%BE%E6%BF%80%E6%B4%BB%E7%AE%97%E6%A2%AF%E5%BA%A6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="与流水线和序列并行一起算账" tabindex="-1">与流水线和序列并行一起算账 <a class="header-anchor" href="#与流水线和序列并行一起算账" aria-label="Permalink to &quot;与流水线和序列并行一起算账&quot;">​</a></h3><p>流水线并行已经让每张卡只持有一部分层，激活份数还随 in-flight 的 microbatch 增加。重计算作用在每张卡的本地层上，减的是「这一阶段里每个 microbatch 的激活」，两者相乘才是真实显存。序列并行 / 上下文并行把激活沿序列切开，单卡的 \\(A\\) 变小，重计算的收益也变小——该切序列还是该重计算，取决于通信墙与计算墙哪边更近。专家并行则在 All-to-All 之后产生专家侧激活，这些张量同样可以纳入检查点范围，但重放时必须还能看到当时的路由结果与容量掩码。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>重计算改变的是峰值显存，不是渐近 FLOPs 的常数项可以忽略。满层重计算大约把前向再做一次，训练 FLOPs 从「一次前向加一次反向」（反向通常约两倍前向）变成接近「两次前向加一次反向」，总计算大约增加百分之三十量级，具体取决于哪些算子被重放。若重放的是已经带宽受限的内核，墙上时间的增幅可能小于 FLOPs 增幅；若重放的是已经算力打满的 GEMM，step time 会接近按比例变慢。</p><p><span class="marginnote">把这笔账算清：反向 \\(\\approx 2\\times\\) 前向，所以不重计算是 \\(1F+2B=3\\) 份前向量级的计算，满层重计算变成 \\(2F+2B=4\\) 份，FLOPs 多约 33%。但若重放的只是带宽受限的小算子，墙钟可能只慢 10–15%——这正是「选择性重计算」存在的理由：只把重放便宜的大张量扔掉重算。</span></p><p>数值上，重放应当与第一次前向足够接近。混合精度里，有的核在前向用某种累加精度，重放若走另一条内核路径，梯度会出现静默偏差。检查点保存的是哪一种 dtype、是否在检查点处强制一次同步，都会进入这条误差。稳定性出问题时应先确认重计算开关，再怀疑优化器。<span class="marginnote">激活重计算不是梯度检查点在「优化器状态」意义上的检查点，也不等于训练中断后的模型 checkpoint。三个词经常混用：一个管反向显存，一个管 Adam 动量是否分片，一个管磁盘上的权重快照。配置项看名字不看实现，很容易把重计算关错。</span></p><h3 id="随机状态与原地算子" tabindex="-1">随机状态与原地算子 <a class="header-anchor" href="#随机状态与原地算子" aria-label="Permalink to &quot;随机状态与原地算子&quot;">​</a></h3><p>Dropout、DropPath、以及某些数据增强在层内发生时，重放必须复现同一掩码。实现通常把 RNG 状态塞进检查点，或把掩码本身当检查点张量。原地修改（in-place ReLU、在同一块缓冲上做归一化）会破坏「输入还在」的假设，检查点包装函数必须禁止这类破坏性更新，或在进入时克隆输入。预训练框架里这类约束已经写成默认，自己改内核时容易踩回去。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>重计算换不来通信。All-Reduce、All-to-All、流水线点对点该发多少还是多少。它也换不来优化器状态：Adam 的一阶二阶矩仍按参数量活着，那是 ZeRO 的问题。当显存瓶颈已经转到优化器或通信缓冲，再加深重计算只会烧计算。</p><p>不是所有激活都值得扔。极小的偏置、已经很小的 LayerNorm 统计量，丢掉再算不回本。值得扔的是体积大、重算相对便宜、或能走已经优化过的融合核的那些。FlashAttention 把注意力中间结果留在 SRAM 里，本身就是一种更激进的「不把大激活写回 HBM」；它与层间检查点是互补关系：前者减层内峰值，后者减跨层驻留。</p>',11)),(E(),i(o,null,{default:e(()=>[l(n,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20TD%0A%20%20MEM%5B%22%E8%AE%AD%E7%BB%83%E6%98%BE%E5%AD%98%E5%9B%9B%E5%9D%97%22%5D%20--%3E%20P%5B%22%E5%8F%82%E6%95%B0%E4%B8%8E%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20MEM%20--%3E%20OPT%5B%22Adam%20%E4%B8%80%E4%BA%8C%E9%98%B6%E7%9F%A9%22%5D%0A%20%20MEM%20--%3E%20ACT%5B%22%E5%89%8D%E5%90%91%E6%BF%80%E6%B4%BB%22%5D%0A%20%20MEM%20--%3E%20BUF%5B%22%E9%80%9A%E4%BF%A1%E7%BC%93%E5%86%B2%22%5D%0A%20%20ACT%20--%20%22%E5%B1%82%E9%97%B4%E6%A3%80%E6%9F%A5%E7%82%B9%22%20--%3E%20CUT1%5B%22%E8%B7%A8%E5%B1%82%E9%A9%BB%E7%95%99%E4%B8%8B%E9%99%8D%22%5D%0A%20%20ACT%20--%20%22FlashAttention%22%20--%3E%20CUT2%5B%22%E5%B1%82%E5%86%85%E5%B3%B0%E5%80%BC%E4%B8%8B%E9%99%8D%22%5D%0A%20%20P%20--%20%22ZeRO%20%E5%88%86%E7%89%87%22%20--%3E%20CUT3%5B%22%E5%8F%A6%E4%B8%80%E9%97%A8%E6%8A%80%E6%9C%AF%E7%AE%A1%22%5D%0A%20%20BUF%20--%20%22%E9%87%8D%E8%AE%A1%E7%AE%97%E7%AE%A1%E4%B8%8D%E5%88%B0%22%20--%3E%20KEEP%5B%22%E4%BF%9D%E6%8C%81%E4%B8%8D%E5%8F%98%22%5D%0A%20%20OPT%20--%20%22%E9%87%8D%E8%AE%A1%E7%AE%97%E7%AE%A1%E4%B8%8D%E5%88%B0%22%20--%3E%20KEEP%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">这张图回答的是「重计算到底省哪一块」：它只碰「前向激活」这一格。参数、Adam 状态要靠 ZeRO 分片，通信要靠拓扑与Overlap，都和重计算无关。所以排显存瓶颈时先分清四块谁在爆——瓶颈在优化器状态时加深重计算，只会白烧三成算力。</span></p><p>推理一般不需要这条技术。推理没有反向，激活只在当前步存活。不要把训练配置里的 checkpointing 原样搬到服务进程。<span class="marginnote">报告「用重计算把序列从 4k 拉到 32k」时，应同时报告 step time 增加了多少、以及重计算是满层还是选择性。只报能跑起来，会把三十个百分点的算力税藏进扩展实验里，后面的扩展律拟合会被污染。</span></p><p>Chen 等人的分析针对的是一般深度网络的链式结构。Transformer 有残差、有并行注意力-FFN、有 MoE 的动态路由，检查点边界要画在「重放仍是确定函数」的位置。路由决策若在检查点之外重新发生，专家侧的重计算会对错专家。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>激活重计算只保存部分前向张量，反向时从检查点重放，用计算换显存。</li><li>思想来自 Chen 等人 2016 年对深度网络次线性内存的分段检查点。</li><li>预训练里通常按 Transformer 层设检查点，再对注意力等大张量做选择性保存。</li><li>满层重计算大约增加三成量级的训练 FLOPs，墙上时间取决于重放内核是否算力受限。</li><li>必须保存随机状态与路由结果，否则重放不是同一个前向。</li><li>它不节省通信和优化器状态；瓶颈不在激活时不应再加深重计算。</li><li>出处：Chen et al., <em>Training Deep Nets with Sublinear Memory Cost</em>, 2016。后续预训练框架中的满重计算与选择性重计算是同一思想的工程分层。</li></ul>',5))])}const T=s(p,[["render",h]]);export{u as __pageData,T as default};
